<template><section class="page-content"><div class="page-heading"><div><p class="eyebrow">PIUTANG PELANGGAN</p><h1>Utang</h1><p class="page-description">Pantau transaksi utang dan catat pelunasan pelanggan.</p></div></div><section class="panel"><div class="panel-header"><div><h2>Daftar Piutang</h2><p>{{ debts.length }} piutang tercatat</p></div></div><div class="table-wrap"><table><thead><tr><th>Pelanggan</th><th>Nomor Transaksi</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="debt in debts" :key="debt.id"><td>{{ debt.pelangganNama }}</td><td>{{ debt.nomor }}</td><td>{{ formatRupiah(debt.total) }}</td><td><span :class="['status-badge', debt.status === 'paid' ? 'status-locked' : 'status-draft']">{{ debt.status === 'paid' ? 'Lunas' : 'Belum Lunas' }}</span></td><td><button v-if="debt.status !== 'paid'" class="table-action" type="button" @click="settle(debt)">Lunasi</button></td></tr><tr v-if="!debts.length"><td colspan="5" class="empty-cell">Belum ada data piutang.</td></tr></tbody></table></div></section></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import Swal from 'sweetalert2'; import { collection, getDocs, query, where, updateDoc, doc } from 'firebase/firestore'; import { db } from '@/firebase'; import { authState } from '@/auth'; const debts=ref<any[]>([]); const base=()=>`warungs/${authState.warungId}`; const formatRupiah=(value:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0); const load=async()=>{if(!authState.warungId)return; const snapshot=await getDocs(query(collection(db,base(),'sales'),where('metodePembayaran','==','utang'))); debts.value=snapshot.docs.map((item)=>({id:item.id,...item.data()}))}; const settle=async(debt:any)=>{const result=await Swal.fire({title:'Pelunasan utang',text:`Pilih metode pelunasan untuk ${formatRupiah(debt.total)}`,input:'select',inputOptions:{cash:'Cash',qris:'QRIS'},inputPlaceholder:'Pilih metode',showCancelButton:true,confirmButtonText:'Simpan',cancelButtonText:'Batal'}); if(result.isConfirmed&&result.value){await updateDoc(doc(db,base(),'sales',debt.id),{debtStatus:'paid',settledAt:new Date().toISOString(),settlementMethod:result.value});await load();await Swal.fire({title:'Utang lunas',icon:'success',confirmButtonColor:'#2563eb'})}}; onMounted(load);
</script>
